"""Summarize mailtodo letters without changing the input tree."""
import argparse
from datetime import datetime
import json
from pathlib import Path
import re


NAME = re.compile(r"^\d{8}T\d{4}[-_]")
REQUIRED = ("id", "from", "to", "status", "at")
RESOLVING = {"DONE", "BLOCKED", "NEEDS-USER", "FAILED"}


def read_letter(path, now):
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except (OSError, UnicodeError):
        return None, "no_frontmatter"
    if not lines or lines[0] != "---":
        return None, "no_frontmatter"
    try:
        end = lines.index("---", 1)
    except ValueError:
        return None, "no_frontmatter"
    fields = {}
    for line in lines[1:end]:
        if ": " in line:
            key, value = line.split(": ", 1)
            fields[key] = value
    if any(not fields.get(key) for key in REQUIRED):
        return None, "no_field"
    try:
        at = datetime.fromisoformat(fields["at"])
    except ValueError:
        return None, "no_field"
    if at.tzinfo is None or at.utcoffset() is None:
        at = at.replace(tzinfo=now.tzinfo)
    if not NAME.match(path.name):
        return None, "bad_name"
    try:
        datetime.strptime(path.name[:13], "%Y%m%dT%H%M")
    except ValueError:
        return None, "bad_name"
    return {"id": fields["id"], "from": fields["from"],
            "to": fields["to"], "status": fields["status"],
            "re": fields.get("re", ""), "at": at}, None


def candidates(root):
    boxes = {}
    paths = []
    for box in root.iterdir():
        if box.name.startswith(".") or box.is_symlink() or not box.is_dir():
            continue
        inbox = box / "inbox"
        if inbox.is_symlink() or not inbox.is_dir():
            continue
        boxes[box.name] = {"inbox": {}, "done": 0}
        for where, directory in (("inbox", inbox), ("done", inbox / "done")):
            if directory.is_symlink() or not directory.is_dir():
                continue
            for path in directory.iterdir():
                if (not path.name.startswith(".") and path.suffix == ".md"
                        and not path.is_symlink() and path.is_file()):
                    paths.append((path.relative_to(root).as_posix(), path, box.name, where))
    return boxes, sorted(paths)


def summarize(root, now):
    boxes, paths = candidates(root)
    bad = []
    valid = []
    ids = set()
    for relative, path, box, where in paths:
        letter, why = read_letter(path, now)
        if why is None and letter["id"] in ids:
            why = "dup_id"
        if why is not None:
            bad.append({"file": relative, "why": why})
            continue
        ids.add(letter["id"])
        letter["where"] = where
        valid.append(letter)
        if where == "done":
            boxes[box]["done"] += 1
        else:
            counts = boxes[box]["inbox"]
            counts[letter["status"]] = counts.get(letter["status"], 0) + 1
    resolved = {letter["re"] for letter in valid
                if letter["re"] and letter["status"] in RESOLVING}
    opened = [{"id": letter["id"], "from": letter["from"],
               "to": letter["to"], "where": letter["where"],
               "age_min": int((now - letter["at"]).total_seconds() // 60)}
              for letter in valid
              if letter["status"] == "REQUEST" and letter["id"] not in resolved]
    opened.sort(key=lambda item: (item["to"], item["id"]))
    return {"v": 1, "open": opened,
            "boxes": {name: {"inbox": dict(sorted(boxes[name]["inbox"].items())),
                             "done": boxes[name]["done"]} for name in sorted(boxes)},
            "bad": sorted(bad, key=lambda item: (item["file"], item["why"]))}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only mailtodo summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    if not args.folder.is_dir():
        parser.error("folder is not a directory")
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO datetime with a timezone")
    if now.tzinfo is None or now.utcoffset() is None:
        parser.error("--now must have a timezone")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
